head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/**
 * @method
 * @name fn_PrintPreView
 * @description desc
 * @param {string} _rexName desc
 * @param {string} _dataType desc
 * @param {string} _dataLocation desc
 * @param {string} _dataXPath desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_PrintPreView = function(_rexName, _dataType, _dataLocation, _dataXPath) {
    // 필수 - rexpert선언 
    var oRptMainParam = rex_GetgoDictionay();
    oRptMainParam.put("rex_rptname", _rexName);
    oRptMainParam.put("rex_datatype", _dataType);
    oRptMainParam.put("rex_data", "http://" + location.host + _dataLocation);
    oRptMainParam.put("rex_xpath", _dataXPath);

    // 옵션 - 파라미터 정의
    oRptMainParam.put("test_data", "사용자 정의 파라미터");

    // MarkAny(위변조방지) 옵션 (상장외부리포트 필수)
    oRptMainParam.put("rex_markany", "true");
    oRptMainParam.put("rex_markany_param", "dllname=MAePageSAFERRexpert.dll;datafilename=MaPrintInfoKrxRex.dat;enablecapture=0;enablespool=0;enableprinter=0;enableprinterInfo=0;printeroption=3;imagesaferoption=0");
    oRptMainParam.put("rex_markany_cellwidth", "16"); //사이즈 조정
    oRptMainParam.put("rex_markany_cellheight", "2"); //사이즈 조정 
    oRptMainParam.put("rex_markany_path", "http://" + location.host + "/markany/jsp/MaFpsCommon.jsp");
    oRptMainParam.put("rex_markany_setpagedata", "MaPrintInfoKrxRex.dat");

    // 옵션 - 팝업설정
    var rex_gsPreViewFeaturesModalCustom = "center:yes;resizable__no;scroll:no;status:no;dialogWidth:825px;dialogHeight:768px";
    oRptMainParam.put("rex_open_window", rex_gsPreViewFeaturesModalCustom);

    // preview 팝업 열기
    rex_gfRexRptOpen("popup", oRptMainParam);
};
